<?php
require_once __DIR__ . '/config/database.php'; require_once __DIR__ . '/includes/functions.php'; require_role(['admin','organizer']);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$app=(int)$_POST['application_id'];$event=(int)$_POST['event_id'];$status=$_POST['status']==='present'?'present':'absent';$s=$pdo->prepare("INSERT INTO attendance(event_id,application_id,marked_by,status,marked_at) SELECT ?,?,?,?,NOW() WHERE EXISTS(SELECT 1 FROM volunteer_applications WHERE id=? AND event_id=? AND status='approved') ON DUPLICATE KEY UPDATE status=VALUES(status),marked_by=VALUES(marked_by),marked_at=NOW()");$s->execute([$event,$app,current_user()['id'],$status,$app,$event]);flash('Attendance saved.');redirect('attendance.php');}
$pageTitle='Attendance';$approved=$pdo->query("SELECT va.id,va.event_id,u.name,e.title AS event_title,a.status AS attendance_status FROM volunteer_applications va JOIN users u ON u.id=va.student_id JOIN events e ON e.id=va.event_id LEFT JOIN attendance a ON a.application_id=va.id WHERE va.status='approved' ORDER BY e.event_date DESC,u.name")->fetchAll();require __DIR__.'/includes/header.php';
?>
<section class="page-heading"><span class="eyebrow">EVENT OPERATIONS</span><h1>Volunteer attendance</h1><p>Record attendance for approved volunteers.</p></section>
<div class="table-wrap"><table><thead><tr><th>Volunteer</th><th>Event</th><th>Current status</th><th>Update attendance</th></tr></thead><tbody><?php foreach($approved as $a):?><tr><td><?=e($a['name'])?></td><td><?=e($a['event_title'])?></td><td><?=e(ucfirst($a['attendance_status']??'Not marked'))?></td><td><form method="post" class="inline-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="application_id" value="<?=$a['id']?>"><input type="hidden" name="event_id" value="<?=$a['event_id']?>"><button class="btn btn-small btn-primary" name="status" value="present">Present</button><button class="btn btn-small btn-danger" name="status" value="absent">Absent</button></form></td></tr><?php endforeach;?><?php if(!$approved):?><tr><td colspan="4">No approved volunteers to mark.</td></tr><?php endif;?></tbody></table></div>
<?php require __DIR__.'/includes/footer.php';?>
